    management_item_code, achievement_date, achievement_status, attachment_ref,
    created_by, updated_by, request_id
)
VALUES (
    'FR-029', #{managementNo}, #{userId}, #{organization}, #{year},
    #{code}, #{date}, 'DRAFT', #{attachments}, #{userId}, #{userId}, #{requestId}
)

INSERT INTO employment_rate_improvement_achievement_details (
    achievement_id, special_lecture_start_date, special_lecture_end_date, mock_exam_question_period,
    created_by, updated_by
)
